<?php
namespace App\Services;
use App\Models\{UmkmDisbursement,UmkmDisbursementAllocation,UmkmDisbursementEvent,UmkmEntitlement,UmkmEntitlementEvent,UmkmStore,User};
use App\Support\UmkmEntitlementEventType;
use App\Support\UmkmEntitlementStatus;
use Illuminate\Auth\Access\AuthorizationException;
use Illuminate\Http\UploadedFile;
use Illuminate\Support\Facades\{DB,Storage};
use Illuminate\Validation\ValidationException;
class UmkmDisbursementTransferService {
 public function record(UmkmDisbursement $d, User $admin, string $reference, string $at, string $amount, UploadedFile $proof): UmkmDisbursement { $this->admin($admin); if($amount !== (string)$d->requested_amount) throw ValidationException::withMessages(['transfer_amount'=>'Nominal harus sama dengan pengajuan.']); $path=$proof->store('umkm-disbursement-proofs','local'); try{return $this->tx($d,function($x)use($admin,$reference,$at,$amount,$path){if($x->status!=='approved'||$x->transfer_recorded_by) $this->bad('Transfer tidak dapat dicatat.');$x->forceFill(['transfer_reference'=>trim($reference),'transfer_amount'=>$amount,'transfer_recorded_at'=>$at,'transfer_proof_path'=>$path,'transfer_recorded_by'=>$admin->id])->save();$this->event($x,$admin,'transfer_recorded','approved','approved');return $x;});}catch(\Throwable $e){Storage::disk('local')->delete($path);throw $e;} }
 public function verify(UmkmDisbursement $d, User $admin): UmkmDisbursement {$this->admin($admin);return $this->tx($d,function($x)use($admin){if($x->status==='paid')return $x;if($x->status!=='approved'||!$x->transfer_recorded_by||$x->transfer_recorded_by===$admin->id||!$x->transfer_reference||!$x->transfer_proof_path)$this->bad('Transfer belum layak diverifikasi.');$alloc=UmkmDisbursementAllocation::where('umkm_disbursement_id',$x->id)->orderBy('id')->lockForUpdate()->get();foreach($alloc as $a){$e=UmkmEntitlement::whereKey($a->umkm_entitlement_id)->lockForUpdate()->firstOrFail();if($e->status!==UmkmEntitlementStatus::RESERVED)$this->bad('Reservation tidak valid.');$e->forceFill(['status'=>'settled','settled_at'=>now()])->save();$a->forceFill(['entitlement_reservation_lock'=>null])->save();UmkmEntitlementEvent::create(['umkm_entitlement_id'=>$e->id,'actor_id'=>$admin->id,'event_type'=>UmkmEntitlementEventType::SETTLED,'amount'=>$a->amount,'from_status'=>'reserved','to_status'=>'settled','idempotency_key'=>$this->key('settled',$e->id,$x->id)]);} $x->forceFill(['status'=>'paid','paid_by'=>$admin->id,'paid_at'=>now(),'transfer_verified_by'=>$admin->id,'transfer_verified_at'=>now(),'active_request_lock'=>null])->save();$this->event($x,$admin,'transfer_verified','approved','paid');$this->event($x,$admin,'paid','approved','paid');return $x;});}
 private function tx(UmkmDisbursement $d,callable $f):UmkmDisbursement{return DB::transaction(function()use($d,$f){UmkmStore::whereKey($d->umkm_store_id)->lockForUpdate()->firstOrFail();return $f(UmkmDisbursement::whereKey($d->id)->lockForUpdate()->firstOrFail());});}
 private function event($d,$u,$t,$f,$to){UmkmDisbursementEvent::firstOrCreate(['idempotency_key'=>$this->key($t,$d->id,$d->id)],['umkm_disbursement_id'=>$d->id,'actor_id'=>$u->id,'event_type'=>$t,'from_status'=>$f,'to_status'=>$to]);}
 private function key($t,$id,$s){$h=md5("ud:$t:$id:$s");return substr($h,0,8).'-'.substr($h,8,4).'-5'.substr($h,13,3).'-8'.substr($h,17,3).'-'.substr($h,20,12);}
 private function admin(User $u){if($u->role!=='admin_bumdes')throw new AuthorizationException('Hanya Admin BUMDes.');} private function bad($m):never{throw ValidationException::withMessages(['disbursement'=>$m]);}
}
